using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_ec7d4ef5b87f4215bc1be4aeb8309f24;

public class HardcodedAuthenticationStateProvider : AuthenticationStateProvider
{
    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        var user = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(user));
    }
}

@page "/profile"
@using Microsoft.AspNetCore.Components.Authorization
@using System.Security.Claims
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto

<h1>Profile</h1>

<p><strong>Name:</strong> @_userName</p>

<h2>Roles</h2>
<ul>
    @foreach (var role in _roles)
    {
        <li>@role</li>
    }
</ul>

@code {
    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    private string _userName = string.Empty;
    private List<string> _roles = new();

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            _userName = state.User.Identity?.Name ?? "Unknown";
            _roles = state.User.Claims
